  Object.assign(DICT, {"Profile":{"tr":"Profil","fr":"Profil","ru":"Профиль"},"available now":{"tr":"şimdi müsait","fr":"disponible maintenant","ru":"доступен сейчас"},"Available now":{"tr":"Şimdi müsait","fr":"Disponible maintenant","ru":"Доступен сейчас"},"Employer":{"tr":"İşveren","fr":"Employeur","ru":"Работодатель"},"Full CVs, documents and video interviews within 4 working hours.":{"tr":"4 iş saati içinde tam CV’ler, belgeler ve video mülakatlar.","fr":"CV complets, documents et entretiens vidéo sous 4 heures ouvrées.","ru":"Полные CV, документы и видеоинтервью в течение 4 рабочих часов."},"Which roles and how many workers?":{"tr":"Hangi pozisyonlar ve kaç işçi?","fr":"Quels postes et combien de travailleurs ?","ru":"Какие должности и сколько работников?"},"City, sector and target start date (optional)":{"tr":"Şehir, sektör ve hedef başlangıç tarihi (isteğe bağlı)","fr":"Ville, secteur et date de début souhaitée (facultatif)","ru":"Город, отрасль и желаемая дата старта (необязательно)"},"Request candidates →":{"tr":"Aday talep edin →","fr":"Demander des candidats →","ru":"Запросить кандидатов →"},"HR agency":{"tr":"İK ajansı","fr":"Agence RH","ru":"HR-агентство"},"Supply for your clients":{"tr":"Müşterileriniz için tedarik","fr":"Fournir pour vos clients","ru":"Поставка для ваших клиентов"},"We supply the workers and file the permits — your client stays yours.":{"tr":"İşçileri biz tedarik ederiz ve izinleri biz sunarız — müşteriniz sizin kalır.","fr":"Nous fournissons les travailleurs et déposons les permis — votre client reste le vôtre.","ru":"Мы предоставляем работников и оформляем разрешения — ваш клиент остаётся вашим."},"Which roles do your clients need, and what volume?":{"tr":"Müşterileriniz hangi pozisyonlara ve ne hacimde ihtiyaç duyuyor?","fr":"Quels postes vos clients recherchent-ils, et en quel volume ?","ru":"Какие должности нужны вашим клиентам и в каком объёме?"},"Sectors you serve and cities (optional)":{"tr":"Hizmet verdiğiniz sektörler ve şehirler (isteğe bağlı)","fr":"Secteurs desservis et villes (facultatif)","ru":"Обслуживаемые отрасли и города (необязательно)"},"Request supply →":{"tr":"Tedarik talep edin →","fr":"Demander une fourniture →","ru":"Запросить поставку →"},"English (basic)":{"tr":"İngilizce (temel)","fr":"Anglais (notions)","ru":"Английский (базовый)"},"English (good)":{"tr":"İngilizce (iyi)","fr":"Anglais (bon)","ru":"Английский (хороший)"},"English (fluent)":{"tr":"İngilizce (akıcı)","fr":"Anglais (courant)","ru":"Английский (свободный)"},"Turkish (basic)":{"tr":"Türkçe (temel)","fr":"Turc (notions)","ru":"Турецкий (базовый)"},"Turkish (basic), Russian":{"tr":"Türkçe (temel), Rusça","fr":"Turc (notions), russe","ru":"Турецкий (базовый), русский"},"Turkish (good), Russian":{"tr":"Türkçe (iyi), Rusça","fr":"Turc (bon), russe","ru":"Турецкий (хороший), русский"},"Turkish (good), Russian, English":{"tr":"Türkçe (iyi), Rusça, İngilizce","fr":"Turc (bon), russe, anglais","ru":"Турецкий (хороший), русский, английский"},"Gulf experience":{"tr":"Körfez deneyimi","fr":"Expérience dans le Golfe","ru":"Опыт работы в Персидском заливе"},"Pipe welding":{"tr":"Boru kaynağı","fr":"Soudure de tuyauterie","ru":"Сварка трубопроводов"},"Night shifts OK":{"tr":"Gece vardiyasına uygun","fr":"Accepte les nuits","ru":"Готов к ночным сменам"},"Machine Operator":{"tr":"Makine Operatörü","fr":"Opérateur machine","ru":"Оператор станка"},"Textile lines":{"tr":"Tekstil hatları","fr":"Lignes textiles","ru":"Текстильные линии"},"Team of 4 available":{"tr":"4 kişilik ekip müsait","fr":"Équipe de 4 disponible","ru":"Доступна команда из 4 человек"},"Team of 12":{"tr":"12 kişilik ekip","fr":"Équipe de 12","ru":"Команда из 12 человек"},"Industrial wiring":{"tr":"Endüstriyel tesisat","fr":"Câblage industriel","ru":"Промышленная электропроводка"},"Site supervisor":{"tr":"Şantiye şefi","fr":"Chef de chantier","ru":"Прораб"},"Season-ready":{"tr":"Sezona hazır","fr":"Prêt pour la saison","ru":"Готов к сезону"},"Kitchen Steward":{"tr":"Mutfak Görevlisi","fr":"Commis de cuisine","ru":"Работник кухни"},"Hotel chain":{"tr":"Otel zinciri","fr":"Chaîne hôtelière","ru":"Гостиничная сеть"},"HACCP trained":{"tr":"HACCP eğitimli","fr":"Formé HACCP","ru":"Обучен HACCP"},"Construction Labourer":{"tr":"İnşaat İşçisi","fr":"Manœuvre du bâtiment","ru":"Строительный рабочий"},"Formwork":{"tr":"Kalıp işi","fr":"Coffrage","ru":"Опалубка"},"Tomato & pepper":{"tr":"Domates ve biber","fr":"Tomate et poivron","ru":"Томаты и перец"},"Hotel projects":{"tr":"Otel projeleri","fr":"Projets hôteliers","ru":"Отельные проекты"},"A la carte":{"tr":"A la carte","fr":"À la carte","ru":"À la carte"},"Antalya season":{"tr":"Antalya sezonu","fr":"Saison d’Antalya","ru":"Сезон в Анталье"},"Textile Machine Operator":{"tr":"Tekstil Makine Operatörü","fr":"Opérateur de machine textile","ru":"Оператор текстильной машины"},"Knitting lines":{"tr":"Örme hatları","fr":"Lignes de tricotage","ru":"Вязальные линии"},"Team leader":{"tr":"Ekip lideri","fr":"Chef d’équipe","ru":"Руководитель группы"},"Within 30 days":{"tr":"30 gün içinde","fr":"Sous 30 jours","ru":"В течение 30 дней"},"Next season":{"tr":"Gelecek sezon","fr":"La saison prochaine","ru":"В следующем сезоне"},"How current is this list?":{"tr":"Bu liste ne kadar güncel?","fr":"À quel point cette liste est-elle à jour ?","ru":"Насколько актуален этот список?"},"The profiles here are a live sample of our portal, refreshed weekly. Our full pool holds 200+ verified CVs, so if you cannot see the profession you need, ask — matching profiles usually reach you the same day.":{"tr":"Buradaki profiller portalımızın canlı bir örneğidir ve haftalık olarak yenilenir. Tam havuzumuzda 200+ doğrulanmış CV var; aradığınız mesleği göremiyorsanız sorun — eşleşen profiller genellikle aynı gün size ulaşır.","fr":"Les profils présentés sont un échantillon en direct de notre portail, actualisé chaque semaine. Notre vivier complet compte plus de 200 CV vérifiés : si vous ne voyez pas le métier recherché, demandez — les profils correspondants vous parviennent généralement le jour même.","ru":"Профили здесь — живая выборка из нашего портала, обновляется еженедельно. В полном пуле более 200 проверенных CV, так что если нужной профессии не видно — спросите: подходящие профили обычно приходят в тот же день."},"Why are names and photos hidden?":{"tr":"İsimler ve fotoğraflar neden gizli?","fr":"Pourquoi les noms et les photos sont-ils masqués ?","ru":"Почему скрыты имена и фотографии?"},"Candidate data is protected under KVKK, so public profiles are anonymised. Once you request a profile, we share the full CV, documents, photo and the recorded video interview with you directly.":{"tr":"Aday verileri KVKK kapsamında korunur, bu yüzden herkese açık profiller anonimleştirilir. Bir profil talep ettiğinizde tam CV’yi, belgeleri, fotoğrafı ve kayıtlı video mülakatı doğrudan sizinle paylaşırız.","fr":"Les données des candidats sont protégées par la loi KVKK, les profils publics sont donc anonymisés. Dès que vous demandez un profil, nous vous transmettons directement le CV complet, les documents, la photo et l’entretien vidéo enregistré.","ru":"Данные кандидатов защищены законом KVKK, поэтому публичные профили анонимизированы. После запроса профиля мы напрямую передаём вам полное CV, документы, фото и записанное видеоинтервью."},"Can I interview the candidate before deciding?":{"tr":"Karar vermeden önce adayla mülakat yapabilir miyim?","fr":"Puis-je passer un entretien avec le candidat avant de décider ?","ru":"Можно ли провести интервью с кандидатом до решения?"},"Yes, and we recommend it. After you request a profile you get the recorded interview first, then we arrange a live video call with the candidate. Nothing is signed until you approve the person.":{"tr":"Evet ve öneriyoruz. Bir profil talep ettikten sonra önce kayıtlı mülakatı alırsınız, ardından adayla canlı görüntülü görüşme ayarlarız. Kişiyi onaylamadan hiçbir şey imzalanmaz.","fr":"Oui, et nous le recommandons. Après votre demande de profil, vous recevez d’abord l’entretien enregistré, puis nous organisons un appel vidéo en direct avec le candidat. Rien n’est signé avant votre approbation.","ru":"Да, и мы это рекомендуем. После запроса профиля вы сначала получаете записанное интервью, затем мы организуем живой видеозвонок с кандидатом. Ничего не подписывается до вашего одобрения."},"Is a candidate reserved once I request them?":{"tr":"Bir adayı talep ettiğimde rezerve edilir mi?","fr":"Un candidat est-il réservé dès que je le demande ?","ru":"Бронируется ли кандидат после запроса?"},"We hold a profile for you while your decision is pending, and tell you honestly if another employer is also in process for the same person. If someone is taken, we send equivalent profiles from the pool.":{"tr":"Kararınız beklerken profili sizin için tutuyoruz ve aynı kişi için başka bir işverenin de süreçte olup olmadığını dürüstçe söylüyoruz. Biri alınmışsa havuzdan eşdeğer profiller gönderiyoruz.","fr":"Nous réservons le profil pendant que vous décidez et vous disons honnêtement si un autre employeur est également en cours sur la même personne. Si quelqu’un est pris, nous envoyons des profils équivalents du vivier.","ru":"Мы держим профиль за вами, пока вы принимаете решение, и честно сообщаем, если по этому же человеку идёт процесс с другим работодателем. Если кандидат занят, пришлём равноценные профили из пула."},"Who files the work permit for these candidates?":{"tr":"Bu adaylar için çalışma iznini kim sunar?","fr":"Qui dépose le permis de travail pour ces candidats ?","ru":"Кто оформляет разрешение на работу для этих кандидатов?"},"How fast can a candidate from this page start?":{"tr":"Bu sayfadaki bir aday ne kadar hızlı başlayabilir?","fr":"À quelle vitesse un candidat de cette page peut-il commencer ?","ru":"Как быстро кандидат с этой страницы может начать работу?"},"Because these profiles are already skill-tested and permit-ready, the file goes to the Ministry within days of your approval. Workers already in Turkey typically start in 4–6 weeks; candidates abroad in about 8–10 weeks.":{"tr":"Bu profiller zaten beceri testinden geçmiş ve izne hazır olduğu için dosya, onayınızdan günler sonra Bakanlığa gider. Türkiye’de bulunan işçiler genellikle 4–6 haftada, yurt dışındaki adaylar yaklaşık 8–10 haftada başlar.","fr":"Comme ces profils sont déjà testés et prêts pour le permis, le dossier part au ministère quelques jours après votre approbation. Les travailleurs déjà en Turquie commencent généralement en 4 à 6 semaines ; les candidats à l’étranger en 8 à 10 semaines environ.","ru":"Поскольку эти профили уже прошли профтест и готовы к оформлению, дело уходит в министерство через считанные дни после вашего одобрения. Работники, уже находящиеся в Турции, обычно начинают через 4–6 недель, кандидаты из-за рубежа — примерно через 8–10 недель."},"What if the worker leaves or does not perform?":{"tr":"İşçi ayrılırsa veya beklentiyi karşılamazsa ne olur?","fr":"Et si le travailleur part ou ne convient pas ?","ru":"А если работник уйдёт или не справится?"},"Do I pay anything to see the profiles?":{"tr":"Profilleri görmek için bir ödeme yapıyor muyum?","fr":"Dois-je payer pour voir les profils ?","ru":"Нужно ли платить за просмотр профилей?"},"No. Browsing, requesting CVs and interviewing candidates costs nothing, and there is no upfront fee. Commercial terms are agreed in writing before any placement.":{"tr":"Hayır. Göz atmak, CV talep etmek ve adaylarla mülakat yapmak ücretsizdir ve peşin ücret yoktur. Ticari koşullar herhangi bir yerleştirmeden önce yazılı olarak kararlaştırılır.","fr":"Non. Consulter, demander des CV et passer des entretiens ne coûte rien, et il n’y a aucun frais initial. Les conditions commerciales sont convenues par écrit avant tout placement.","ru":"Нет. Просмотр, запрос CV и интервью с кандидатами бесплатны, предоплаты нет. Коммерческие условия согласуются письменно до любого трудоустройства."},"Updated weekly":{"tr":"Haftalık güncellenir","fr":"Mis à jour chaque semaine","ru":"Обновляется еженедельно"},"Soonest available":{"tr":"En erken müsait","fr":"Disponible au plus tôt","ru":"Доступен раньше всех"},"Most experience":{"tr":"En fazla deneyim","fr":"Plus d’expérience","ru":"Больше опыта"},"Recently added":{"tr":"Yeni eklenen","fr":"Ajoutés récemment","ru":"Недавно добавленные"},"Profession A–Z":{"tr":"Meslek A–Z","fr":"Métier A–Z","ru":"Профессия А–Я"},"more)":{"tr":"daha)","fr":"de plus)","ru":"ещё)"},"profile attached":{"tr":"profil eklendi","fr":"profil joint","ru":"профиль прикреплён"},"profiles attached":{"tr":"profil eklendi","fr":"profils joints","ru":"профилей прикреплено"},"Hide ▲":{"tr":"Gizle ▲","fr":"Masquer ▲","ru":"Скрыть ▲"},"Show ▼":{"tr":"Göster ▼","fr":"Afficher ▼","ru":"Показать ▼"},"All professions":{"tr":"Tüm meslekler","fr":"Tous les métiers","ru":"Все профессии"},"All countries":{"tr":"Tüm ülkeler","fr":"Tous les pays","ru":"Все страны"},"Any experience":{"tr":"Her deneyim","fr":"Toute expérience","ru":"Любой опыт"},"0–3 years":{"tr":"0–3 yıl","fr":"0–3 ans","ru":"0–3 года"},"4–7 years":{"tr":"4–7 yıl","fr":"4–7 ans","ru":"4–7 лет"},"8+ years":{"tr":"8+ yıl","fr":"8+ ans","ru":"8+ лет"},"8+ yrs":{"tr":"8+ yıl","fr":"8+ ans","ru":"8+ лет"},"Any language":{"tr":"Her dil","fr":"Toute langue","ru":"Любой язык"},"Speaks Turkish":{"tr":"Türkçe konuşuyor","fr":"Parle turc","ru":"Говорит по-турецки"},"Good English":{"tr":"İyi İngilizce","fr":"Bon anglais","ru":"Хороший английский"},"Any time":{"tr":"Her zaman","fr":"N’importe quand","ru":"Любое время"},"yrs experience":{"tr":"yıl deneyim","fr":"ans d’expérience","ru":"лет опыта"},"Added to request":{"tr":"Talebe eklendi","fr":"Ajouté à la demande","ru":"Добавлено в запрос"},"Add to request":{"tr":"Talebe ekle","fr":"Ajouter à la demande","ru":"Добавить в запрос"}});
