  Object.assign(DICT, {"Sat":{"tr":"Cmt","fr":"sam.","ru":"сб"},"Sun":{"tr":"Paz","fr":"dim.","ru":"вс"},"Office open now ·":{"tr":"Ofis şu anda açık ·","fr":"Bureau ouvert ·","ru":"Офис открыт ·"},"in Antalya":{"tr":"Antalya’da","fr":"à Antalya","ru":"в Анталье"},"Weekend · WhatsApp is still watched":{"tr":"Hafta sonu · WhatsApp yine takip ediliyor","fr":"Week-end · WhatsApp reste surveillé","ru":"Выходные · WhatsApp всё равно на связи"},"Closed for today":{"tr":"Bugün için kapalı","fr":"Fermé pour aujourd’hui","ru":"На сегодня закрыто"},"Contact:":{"tr":"İletişim:","fr":"Contact :","ru":"Контакт:"},"Phone:":{"tr":"Telefon:","fr":"Téléphone :","ru":"Телефон:"},"Preferred reply:":{"tr":"Tercih edilen yanıt:","fr":"Réponse souhaitée :","ru":"Предпочтительный ответ:"},"Notes:":{"tr":"Notlar:","fr":"Remarques :","ru":"Примечания:"},"employer desk":{"tr":"işveren birimi","fr":"service employeurs","ru":"отдел работодателей"},"Tell us the roles":{"tr":"Pozisyonları bize söyleyin","fr":"Dites-nous les postes","ru":"Назовите должности"},"Job titles and headcount are enough to start — we come back with candidates, timeline and cost.":{"tr":"Başlamak için pozisyon adları ve kişi sayısı yeterli — adaylar, süre ve maliyetle geri döneriz.","fr":"Les intitulés de poste et l’effectif suffisent pour démarrer — nous revenons avec des candidats, un délai et un coût.","ru":"Для старта достаточно названий должностей и количества — вернёмся с кандидатами, сроком и стоимостью."},"Registered company name":{"tr":"Kayıtlı şirket adı","fr":"Raison sociale","ru":"Официальное название компании"},"Roles and headcount":{"tr":"Pozisyonlar ve kişi sayısı","fr":"Postes et effectif","ru":"Должности и количество"},"e.g. 10 welders, 4 CNC operators":{"tr":"örn. 10 kaynakçı, 4 CNC operatörü","fr":"ex. 10 soudeurs, 4 opérateurs CNC","ru":"напр. 10 сварщиков, 4 оператора ЧПУ"},"Send my hiring request":{"tr":"İşe alım talebimi gönder","fr":"Envoyer ma demande de recrutement","ru":"Отправить заявку на наём"},"permit team":{"tr":"izin ekibi","fr":"équipe permis","ru":"отдел разрешений"},"Permit file, no sourcing":{"tr":"Sadece izin dosyası, tedarik yok","fr":"Dossier de permis, sans sourcing","ru":"Только разрешение, без подбора"},"You already have the worker — we run the application, the follow-up and the renewals.":{"tr":"İşçi elinizde zaten var — başvuruyu, takibi ve yenilemeleri biz yürütürüz.","fr":"Vous avez déjà le travailleur — nous gérons la demande, le suivi et les renouvellements.","ru":"Работник у вас уже есть — мы ведём заявление, контроль и продления."},"Worker and role":{"tr":"İşçi ve pozisyon","fr":"Travailleur et poste","ru":"Работник и должность"},"e.g. 1 Uzbek chef, already in Turkey":{"tr":"örn. 1 Özbek aşçı, hâlihazırda Türkiye’de","fr":"ex. 1 chef ouzbek, déjà en Turquie","ru":"напр. 1 узбекский повар, уже в Турции"},"Workplace city":{"tr":"İşyeri şehri","fr":"Ville du lieu de travail","ru":"Город места работы"},"Ask the permit team":{"tr":"İzin ekibine sorun","fr":"Interroger l’équipe permis","ru":"Спросить отдел разрешений"},"partnerships desk":{"tr":"iş ortaklıkları birimi","fr":"service partenariats","ru":"отдел партнёрств"},"HR agencies in Turkey, sourcing agents abroad and training institutes — tell us what you bring.":{"tr":"Türkiye’deki İK ajansları, yurt dışındaki tedarik temsilcileri ve eğitim enstitüleri — ne getirdiğinizi bize söyleyin.","fr":"Agences RH en Turquie, agents de sourcing à l’étranger et instituts de formation — dites-nous ce que vous apportez.","ru":"HR-агентства в Турции, агенты по подбору за рубежом и учебные институты — расскажите, что вы приносите."},"Agency name & country":{"tr":"Ajans adı ve ülke","fr":"Nom de l’agence et pays","ru":"Название агентства и страна"},"e.g. Skyline Manpower, Nepal":{"tr":"örn. Skyline Manpower, Nepal","fr":"ex. Skyline Manpower, Népal","ru":"напр. Skyline Manpower, Непал"},"What you supply":{"tr":"Ne tedarik ediyorsunuz","fr":"Ce que vous fournissez","ru":"Что вы поставляете"},"e.g. welders and masons, 200 on file":{"tr":"örn. kaynakçı ve duvarcı, dosyada 200 kişi","fr":"ex. soudeurs et maçons, 200 au fichier","ru":"напр. сварщики и каменщики, 200 в базе"},"Licence no.":{"tr":"Lisans no.","fr":"N° de licence","ru":"№ лицензии"},"If you have one":{"tr":"Varsa","fr":"Si vous en avez une","ru":"Если есть"},"Send partnership enquiry":{"tr":"İş ortaklığı talebi gönder","fr":"Envoyer une demande de partenariat","ru":"Отправить запрос о партнёрстве"},"A call":{"tr":"Bir arama","fr":"Un appel","ru":"Звонок"},"It lands on the right desk":{"tr":"Doğru birime ulaşır","fr":"Cela arrive au bon service","ru":"Попадает в нужный отдел"},"Hiring, permits and partnerships are three different people here — your message goes to one of them, not a shared inbox.":{"tr":"İşe alım, izinler ve iş ortaklıkları burada üç farklı kişidir — mesajınız ortak bir gelen kutusuna değil, onlardan birine gider.","fr":"Recrutement, permis et partenariats sont trois personnes différentes ici — votre message va à l’une d’elles, pas à une boîte partagée.","ru":"Наём, разрешения и партнёрства здесь — три разных человека; ваше сообщение идёт одному из них, а не в общий ящик."},"You get a human reply":{"tr":"Gerçek bir kişiden yanıt alırsınız","fr":"Vous recevez une réponse humaine","ru":"Вам отвечает живой человек"},"Same day in office hours. Next business morning if you write at night or over the weekend.":{"tr":"Mesai saatlerinde aynı gün. Gece veya hafta sonu yazarsanız bir sonraki iş günü sabahı.","fr":"Le jour même pendant les heures de bureau. Le matin ouvré suivant si vous écrivez la nuit ou le week-end.","ru":"В рабочее время — в тот же день. Если пишете ночью или в выходные — утром следующего рабочего дня."},"A short call to pin it down":{"tr":"Netleştirmek için kısa bir görüşme","fr":"Un court appel pour cadrer","ru":"Короткий звонок для уточнения"},"Roles, headcount, start date, accommodation, budget. Fifteen minutes is usually enough.":{"tr":"Pozisyonlar, kişi sayısı, başlangıç tarihi, konaklama, bütçe. On beş dakika genellikle yeterli.","fr":"Postes, effectif, date de début, logement, budget. Quinze minutes suffisent généralement.","ru":"Должности, количество, дата старта, жильё, бюджет. Обычно достаточно пятнадцати минут."},"Written numbers within 24 hours":{"tr":"24 saat içinde yazılı sayılar","fr":"Des chiffres écrits sous 24 heures","ru":"Письменные цифры в течение 24 часов"},"A quote, or a permit checklist — in writing, so you can take it to your board.":{"tr":"Bir teklif veya izin kontrol listesi — yazılı olarak, yönetim kuruluna sunabilmeniz için.","fr":"Un devis, ou une checklist de permis — par écrit, pour le présenter à votre conseil.","ru":"Расчёт или чек-лист по разрешению — письменно, чтобы вы могли показать руководству."},"Do you charge for a first conversation?":{"tr":"İlk görüşme için ücret alıyor musunuz?","fr":"Facturez-vous un premier échange ?","ru":"Берёте ли вы плату за первую беседу?"},"No. Sourcing, shortlists and the quote itself are free — you pay one agreed service fee only when you accept workers and we start the permit file. There is no consultation charge, no retainer and nothing upfront.":{"tr":"Hayır. Tedarik, kısa listeler ve teklifin kendisi ücretsizdir — yalnızca işçileri kabul ettiğinizde ve izin dosyasını başlattığımızda anlaşılan tek bir hizmet bedeli ödersiniz. Danışmanlık ücreti, ön ödeme veya peşin bir bedel yoktur.","fr":"Non. Le sourcing, les short-lists et le devis lui-même sont gratuits — vous ne payez un unique honoraire convenu que lorsque vous acceptez des travailleurs et que nous ouvrons le dossier de permis. Aucun frais de consultation, aucun acompte, rien d’avance.","ru":"Нет. Подбор, шортлисты и сам расчёт бесплатны — согласованное вознаграждение вы платите только когда принимаете работников и мы открываем дело по разрешению. Ни платы за консультацию, ни аванса, ни предоплаты."},"Which languages can we speak?":{"tr":"Hangi dilleri konuşabiliyoruz?","fr":"Quelles langues parlons-nous ?","ru":"На каких языках мы говорим?"},"Turkish, English, French, Hindi and Russian. Write in whichever you prefer — the reply comes back in the same language.":{"tr":"Türkçe, İngilizce, Fransızca, Hintçe ve Rusça. Hangisini tercih ederseniz onunla yazın — yanıt aynı dilde gelir.","fr":"Turc, anglais, français, hindi et russe. Écrivez dans la langue que vous préférez — la réponse arrive dans la même langue.","ru":"Турецкий, английский, французский, хинди и русский. Пишите на любом удобном — ответим на нём же."},"How fast will someone actually answer?":{"tr":"Gerçekte ne kadar hızlı yanıt alırım?","fr":"En combien de temps aurai-je vraiment une réponse ?","ru":"Насколько быстро действительно ответят?"},"Can you come and see our site first?":{"tr":"Önce gelip sahamızı görebilir misiniz?","fr":"Pouvez-vous venir voir notre site d’abord ?","ru":"Можете сначала приехать и посмотреть наш объект?"},"Yes, and for orders above ten workers we prefer it. We look at the work itself and at the accommodation you offer, because both decide which candidates will actually stay. Antalya and nearby provinces within the week — elsewhere in Turkey by arrangement.":{"tr":"Evet ve on işçinin üzerindeki siparişlerde bunu tercih ediyoruz. İşin kendisine ve sunduğunuz konaklamaya bakıyoruz, çünkü hangi adayların gerçekten kalacağını ikisi birlikte belirliyor. Antalya ve çevre iller hafta içinde — Türkiye’nin diğer yerleri anlaşmayla.","fr":"Oui, et pour les commandes de plus de dix travailleurs nous le préférons. Nous regardons le travail lui-même et le logement proposé, car les deux déterminent quels candidats resteront vraiment. Antalya et les provinces voisines dans la semaine — ailleurs en Turquie sur rendez-vous.","ru":"Да, а для заявок свыше десяти работников мы это предпочитаем. Мы смотрим и на саму работу, и на предлагаемое жильё — вместе они определяют, кто действительно останется. Анталья и соседние регионы — в течение недели, другие регионы Турции — по договорённости."},"I am a worker looking for a job — can I write here?":{"tr":"İş arayan bir işçiyim — buraya yazabilir miyim?","fr":"Je suis un travailleur en recherche d’emploi — puis-je écrire ici ?","ru":"Я работник и ищу работу — могу я написать здесь?"},"Are my details safe?":{"tr":"Bilgilerim güvende mi?","fr":"Mes données sont-elles en sécurité ?","ru":"Мои данные в безопасности?"},"Yes. Details you send are used only to answer your enquiry, under KVKK Law No. 6698, and are never sold or shared with third parties. Ask us to delete them at any time and we do.":{"tr":"Evet. Gönderdiğiniz bilgiler yalnızca talebinizi yanıtlamak için, 6698 sayılı KVKK kapsamında kullanılır ve asla satılmaz veya üçüncü taraflarla paylaşılmaz. Dilediğiniz zaman silmemizi isteyin, sileriz.","fr":"Oui. Les informations que vous envoyez servent uniquement à répondre à votre demande, conformément à la loi KVKK n° 6698, et ne sont jamais vendues ni partagées avec des tiers. Demandez-nous de les supprimer à tout moment et nous le faisons.","ru":"Да. Присланные данные используются только для ответа на ваш запрос согласно закону KVKK № 6698 и никогда не продаются и не передаются третьим лицам. В любой момент попросите удалить — удалим."},"Tomorrow":{"tr":"Yarın","fr":"Demain","ru":"Завтра"},"This week":{"tr":"Bu hafta","fr":"Cette semaine","ru":"На этой неделе"},"a weekday":{"tr":"bir hafta içi günü","fr":"un jour de semaine","ru":"в рабочий день"},"any time":{"tr":"herhangi bir saat","fr":"à tout moment","ru":"в любое время"},"Hide extra details":{"tr":"Ek bilgileri gizle","fr":"Masquer les détails supplémentaires","ru":"Скрыть доп. сведения"},"+ Add extra details (optional)":{"tr":"+ Ek bilgi ekle (isteğe bağlı)","fr":"+ Ajouter des détails (facultatif)","ru":"+ Добавить сведения (необязательно)"},"Hide the slots":{"tr":"Saatleri gizle","fr":"Masquer les créneaux","ru":"Скрыть слоты"},"Pick a day & time":{"tr":"Bir gün ve saat seçin","fr":"Choisir un jour et une heure","ru":"Выберите день и время"},"Lines open now":{"tr":"Hatlar şu anda açık","fr":"Lignes ouvertes","ru":"Линии открыты"},"Lines closed":{"tr":"Hatlar kapalı","fr":"Lignes fermées","ru":"Линии закрыты"},"Looking for a job":{"tr":"İş arıyorum","fr":"Je cherche un emploi","ru":"Ищу работу"},"Goes to the":{"tr":"Şuraya gider:","fr":"Va au","ru":"Направляется в"},"sourcing team":{"tr":"tedarik ekibi","fr":"service sourcing","ru":"отдел подбора"},", any time in office hours":{"tr":", mesai saatleri içinde her zaman","fr":", à tout moment pendant les heures de bureau","ru":", в любое время в рабочие часы"},"Callback requested for":{"tr":"Geri arama talep edildi:","fr":"Rappel demandé pour","ru":"Обратный звонок запрошен на"},"Subscribe to hiring updates":{"tr":"İşe alım güncellemelerine abone olun","fr":"S’abonner aux actualités recrutement","ru":"Подписаться на новости о найме"},"Turkish":{"tr":"Türkçe","fr":"Turc","ru":"Турецкий"},"French":{"tr":"Fransızca","fr":"Français","ru":"Французский"},"Hindi":{"tr":"Hintçe","fr":"Hindi","ru":"Хинди"},"Russian":{"tr":"Rusça","fr":"Russe","ru":"Русский"},"Contact JobsAdmire":{"tr":"JobsAdmire ile iletişime geçin","fr":"Contacter JobsAdmire","ru":"Связаться с JobsAdmire"},"Mon–Fri · 09:00–18:00 (TRT)":{"tr":"Pzt–Cum · 09:00–18:00 (TRT)","fr":"Lun–Ven · 09:00–18:00 (TRT)","ru":"Пн–Пт · 09:00–18:00 (TRT)"},"Mon–Sat · 10:00–19:00 (PKT)":{"tr":"Pzt–Cmt · 10:00–19:00 (PKT)","fr":"Lun–Sam · 10:00–19:00 (PKT)","ru":"Пн–Сб · 10:00–19:00 (PKT)"}});
  // Blog UI chrome (article titles and excerpts stay editorial — see github/translation notes)
  Object.assign(DICT, {"Topic":{"tr":"Konu","fr":"Sujet","ru":"Тема"},"Pick a topic":{"tr":"Konu seçin","fr":"Choisir un sujet","ru":"Выберите тему"},"Search articles…":{"tr":"Yazılarda ara…","fr":"Rechercher des articles…","ru":"Поиск по статьям…"},"Load more articles ↓":{"tr":"Daha fazla yazı ↓","fr":"Charger plus d’articles ↓","ru":"Показать ещё статьи ↓"},"Guides":{"tr":"Rehber","fr":"Guides","ru":"Руководства"},"Weekly":{"tr":"Haftalık","fr":"Hebdomadaire","ru":"Еженедельно"},"New post":{"tr":"Yeni yazı","fr":"Nouvel article","ru":"Новая статья"},"Insights for":{"tr":"için içgörüler","fr":"Analyses pour","ru":"Аналитика для"},"Hiring guides, work permit updates and workforce news from the Turkey–overseas recruitment corridor.":{"tr":"Türkiye ve yurt dışı işe alım koridorundan işe alım rehberleri, çalışma izni güncellemeleri ve iş gücü haberleri.","fr":"Guides de recrutement, actualités des permis de travail et nouvelles du marché du travail sur le corridor Turquie–international.","ru":"Руководства по найму, новости о разрешениях на работу и рынке труда на коридоре Турция — зарубежье."},"New article every week":{"tr":"Her hafta yeni yazı","fr":"Un nouvel article chaque semaine","ru":"Новая статья каждую неделю"},"for “":{"tr":"“","fr":"pour « ","ru":"по «"},"employers":{"tr":"işverenler","fr":"employeurs","ru":"работодателей"},"farms":{"tr":"çiftlikler","fr":"exploitations agricoles","ru":"фермы"},"contractors":{"tr":"müteahhitler","fr":"entreprises de BTP","ru":"подрядчиков"},"factories":{"tr":"fabrikalar","fr":"usines","ru":"заводы"},"hotels":{"tr":"oteller","fr":"hôtels","ru":"отели"}});
